const items = $input.all();
const recipes = [];

for (const item of items) {
  const dataString = item.json.data;

  if (!dataString || typeof dataString !== 'string') continue;

  try {
    const parsedData = JSON.parse(dataString);

    if (!parsedData.data || !Array.isArray(parsedData.data)) continue;

    for (const element of parsedData.data) {
      if (!element.results || !Array.isArray(element.results)) continue;

      for (const result of element.results) {
        try {
          const jsonData = JSON.parse(result.html);

          let recipeData = null;
          if (jsonData['@type'] === 'Recipe') {
            recipeData = jsonData;
          } else if (jsonData['@graph']) {
            recipeData = jsonData['@graph'].find(item => item['@type'] === 'Recipe');
          }

          if (recipeData) {
            recipes.push({
              titre: recipeData.name,
              description: recipeData.description?.replace(/<[^>]*>/g, ''),
              categorie: recipeData.recipeCategory,
              temps_preparation: recipeData.prepTime,
              temps_cuisson: recipeData.cookTime,
              temps_total: recipeData.totalTime,
              portions: recipeData.recipeYield,
              ingredients: recipeData.recipeIngredient || [],
              etapes: (recipeData.recipeInstructions || []).map(step => ({
                nom: step.name || '',
                texte: step.text || step
              })),
              auteur: recipeData.author?.name || recipeData.author,
              image: Array.isArray(recipeData.image) ? recipeData.image[0] : recipeData.image,
              note: recipeData.aggregateRating ? {
                valeur: recipeData.aggregateRating.ratingValue,
                nombre_avis: recipeData.aggregateRating.reviewCount
              } : null,
              url: recipeData.url
            });
          }
        } catch (e) {
          console.error('Erreur parsing result.html:', e.message);
        }
      }
    }
  } catch (e) {
    console.error('Erreur parsing dataString:', e.message);
  }
}

return [{
  json: {
    recette_json: JSON.stringify(recipes[0] || {}, null, 2)
  }
}];

const item = $input.first();
let data = item.json.output;

try {
  if (typeof data === 'string') {
    // Nettoyer les éventuels backticks markdown
    data = data.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    data = JSON.parse(data);
  }

  if (!data || !data.title) {
    throw new Error('Données recette incomplètes : title manquant');
  }

  return [{
    json: {
      title: data.title,
      description: data.description || '',
      category: data.category || null,
      servings: parseInt(data.servings_default) || null,
      minutes_prep: parseInt(data.prep_time) || null,
      minutes_cook: parseInt(data.cook_time) || null,
      minutes_total: parseInt(data.minutes_total) || null,
      difficulty: data.difficulty || null,
      season: data.season || null,
      instructions: JSON.stringify(data.instructions || []),
      ingredients: data.ingredients || []
    }
  }];

} catch (error) {
  throw new Error('Erreur parsing recette : ' + error.message + ' | Data: ' + JSON.stringify(data).substring(0, 200));
}

const recipeData = $('Parse recette').first().json;
const fluxPrompt = $input.first().json.output || '';

return [{
  json: {
    ...recipeData,
    flux_prompt: fluxPrompt.trim()
  }
}];

const falResponse = $input.first().json;
const recipeData = $('Parse recette').first().json;

// Extraire l'URL de l'image depuis la réponse fal.ai
const imageUrl = falResponse?.images?.[0]?.url || null;

if (!imageUrl) {
  throw new Error('Pas d\'image reçue depuis fal.ai : ' + JSON.stringify(falResponse).substring(0, 200));
}

return [{
  json: {
    title: recipeData.title,
    description: recipeData.description,
    category: recipeData.category,
    servings: recipeData.servings,
    minutes_prep: recipeData.minutes_prep,
    minutes_cook: recipeData.minutes_cook,
    minutes_total: recipeData.minutes_total,
    difficulty: recipeData.difficulty,
    season: recipeData.season,
    instructions: recipeData.instructions,
    image_url: imageUrl
  }
}];
